.ds-extension-status { color: var(--green, #0066cc); font-size: calc(12px * var(--text-scale, 1)); line-height: 1.7; overflow-wrap: anywhere; }
.ds-inline-actions { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; min-width: 0; }
.ds-inline-actions button { white-space: nowrap; }
.ds-extension-field { display: flex; flex-direction: column; gap: 7px; min-width: 0; color: var(--ink, #1d1d1f); font-size: calc(14px * var(--text-scale, 1)); line-height: 1.55; }
.ds-extension-field input, .ds-extension-field select, .ds-extension-field textarea { min-width: 0; width: 100%; min-height: 40px; padding: 8px 11px; border: 1px solid var(--field-line, #d2d2d8); border-radius: 8px; background: var(--paper, #ffffff); color: var(--ink, #1d1d1f); font: inherit; }
.ds-extension-field input:disabled, .ds-extension-field select:disabled, .ds-extension-field textarea:disabled { opacity: .65; }
.ds-inline-check { display: inline-flex; align-items: center; gap: 8px; color: var(--muted, #626267); font-size: calc(12px * var(--text-scale, 1)); line-height: 1.6; }
.ds-inline-check input { accent-color: var(--green, #0066cc); width: 17px; height: 17px; margin: 0; flex-shrink: 0; }
.ds-ai-form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 20px 22px; }
.ds-ai-wide { grid-column: 1 / -1; }
.ds-ai-key-actions { margin: 12px 0 22px; }
.ds-ai-actions { gap: 10px; margin-bottom: 14px; }
.ds-ai-profile-form .ds-inline-error { margin-top: 8px; }
